def dprime(x1, x2):
    """x1,x2: neurons * frames """
    u1, u2 = np.nanmean(x1, 1), np.nanmean(x2, 1)
    sig1, sig2 = np.nanstd(x1, 1), np.nanstd(x2, 1)
    return 2 * (u1 - u2) / (sig1 + sig2)      

