from collections import defaultdict
session_records = defaultdict(list)
for path in sorted(glob.glob('/app/data/beh/Beh_*.npy')):
    beh = np.load(path, allow_pickle=True).item()
    for k,v in beh.items():
        session_records[k].append((os.path.basename(path), v))

def arr_equal(a,b):
    if isinstance(a, np.ndarray) and isinstance(b, np.ndarray):
        if a.dtype.kind in 'OUS' or b.dtype.kind in 'OUS':
            return a.shape==b.shape and np.all(a==b)
        return np.array_equal(a,b,equal_nan=True)
    return a==b

for k,recs in sorted(session_records.items()):
    if len(recs) < 2:
        continue
    base_name, base = recs[0]
    diffs = set()
    for name,v in recs[1:]:
        for field in base.keys():
            if field not in v or not arr_equal(base[field], v[field]):
                diffs.add(field)
        for field in v.keys():
            if field not in base:
                diffs.add(field)
    print(k, 'nrecs', len(recs), 'diff_fields', sorted(diffs))
