from collections import defaultdict
session_records = defaultdict(list)
for path in sorted(glob.glob('/app/data/beh/Beh_*.npy')):
    beh = np.load(path, allow_pickle=True).item()
    for k,v in beh.items():
        session_records[k].append((os.path.basename(path), v))

def same(a,b):
    if isinstance(a, np.ndarray) and isinstance(b, np.ndarray):
        if a.shape != b.shape:
            return False
        if a.dtype.kind in 'OUS' or b.dtype.kind in 'OUS':
            try:
                return bool(np.all(a == b))
            except Exception:
                return all(same(x,y) for x,y in zip(a.flat,b.flat))
        return np.array_equal(a,b,equal_nan=True)
    if isinstance(a, list) and isinstance(b, list):
        return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
    if isinstance(a, tuple) and isinstance(b, tuple):
        return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
    if isinstance(a, dict) and isinstance(b, dict):
        return set(a)==set(b) and all(same(a[k],b[k]) for k in a)
    try:
        if isinstance(a, float) or isinstance(b, float):
            if np.isnan(a) and np.isnan(b):
                return True
    except Exception:
        pass
    return a == b

all_diff_fields = defaultdict(set)
for k,recs in sorted(session_records.items()):
    if len(recs) < 2:
        continue
    base_name, base = recs[0]
    for name,v in recs[1:]:
        fields = set(base) | set(v)
        for field in fields:
            if field not in base or field not in v or not same(base.get(field), v.get(field)):
                all_diff_fields[k].add(field)

for k, diffs in all_diff_fields.items():
    print(k, sorted(diffs))
print('unique differing field sets', sorted(set(tuple(sorted(v)) for v in all_diff_fields.values())))
