def parse_base_key(key):
    parts = key.split('_')
    return '_'.join(parts[:-1]) if parts[-1].startswith('swap') else key

def category(name):
    m = re.match(r'([A-Za-z]+)', name)
    return m.group(1).lower() if m else name.lower()

