area_defs = {'V1':[8], 'mHV':[0,1,2,9], 'lHV':[5,6], 'aHV':[3,4]}
quota = 128
offset = 0
sel_chunks = []
for arr in spk_obj:
    nfr = arr.shape[1]
    corr = beh['ft_CorrSpc'][:nfr]
    gray = beh['ft_GraySpc'][:nfr]
    ia = ret[offset:offset+arr.shape[0]]
    corr_mean = arr[:, corr].mean(1)
    gray_mean = arr[:, gray].mean(1)
    corr_var = arr[:, corr].var(1)
    for codes in area_defs.values():
