        if idx.any():
            rows = np.where(idx)[0]
            order = np.argsort(corr_var[idx])[::-1][:quota]
            sel_chunks.append(arr[rows[order]])
    offset += arr.shape[0]
sel = np.concatenate(sel_chunks, axis=0)
print('selected shape', sel.shape)
